// PBR material library + rain/wetness shader extension.
//
// All textures are generated by tools/texgen (original work). Geometry UVs are
// authored in metres; each material sets texture repeat = 1 / tile size.
import * as THREE from 'three';

const TEX = './assets/textures/';

// set name -> { tile (m), kind: 'metal' (ORM.b = metalness) | 'ground' (ORM.b = height) | 'dielectric' }
// macro: 'yard' = world-scale repair/stain/crack-seal mask (yardmask, 64 m); 'container' = per-instance/
// per-band horizontal offset of the paint texture so a 12 m side does not repeat its 3 m tile visibly.
export const SETS = {
  asphalt: { tile: 4, kind: 'ground', macro: 'yard' },
  concrete: { tile: 3, kind: 'ground' },
  container_rust: { tile: 1, kind: 'metal', macro: 'container' },
  container_blue: { tile: 1, kind: 'metal', macro: 'container' },
  container_green: { tile: 1, kind: 'metal', macro: 'container' },
  container_grey: { tile: 1, kind: 'metal', macro: 'container' },
  container_orange: { tile: 1, kind: 'metal', macro: 'container' },
  container_white: { tile: 1, kind: 'metal', macro: 'container' },
  crane_yellow: { tile: 2, kind: 'metal' },
  steel_dark: { tile: 2, kind: 'metal' },
  steel_red: { tile: 2, kind: 'metal' },
  castiron: { tile: 1, kind: 'metal' },
  galvanized: { tile: 1.5, kind: 'metal' },
  hull: { tile: 8, kind: 'dielectric' },
  cladding: { tile: 4, kind: 'metal' },
  wood: { tile: 1.2, kind: 'dielectric' },
  rubber: { tile: 1, kind: 'dielectric' },
  rope: { tile: 0.3, kind: 'dielectric' },
  gunmetal: { tile: 0.25, kind: 'metal' },
  polymer: { tile: 0.25, kind: 'dielectric' },
  fabric_uniform: { tile: 0.5, kind: 'dielectric' },
  fabric_vest: { tile: 0.5, kind: 'dielectric' },
  fabric_glove: { tile: 0.3, kind: 'dielectric' },
  camo_m90: { tile: 0.45, kind: 'dielectric' },
  camo_emr: { tile: 0.4, kind: 'dielectric' },
  olive_knit: { tile: 0.2, kind: 'dielectric' },
  glove_green: { tile: 0.15, kind: 'dielectric' },
  khaki_webbing: { tile: 0.2, kind: 'dielectric' },
  ratnik_green: { tile: 0.4, kind: 'dielectric' },
  boot_leather: { tile: 0.3, kind: 'dielectric' },
  ak_wood: { tile: 0.3, kind: 'dielectric' },
  plum_polymer: { tile: 0.2, kind: 'dielectric' },
};
const SINGLE = ['water_normal', 'puddles_albedo', 'marking_albedo', 'yardmask_albedo', 'skin_detail_normal'];

export const textures = {};
export const WET = {
  uTime: { value: 0 },
  uWetness: { value: 1 },
  tPuddle: { value: null },
  tYard: { value: null },
  tRefl: { value: null },
  uReflMatrix: { value: new THREE.Matrix4() },
  uReflOn: { value: 0 },
};

export async function loadTextures(renderer, anisotropy, onProgress) {
  const loader = new THREE.TextureLoader();
  const jobs = [];
  for (const name of Object.keys(SETS)) for (const map of ['albedo', 'normal', 'orm']) jobs.push(`${name}_${map}`);
  jobs.push(...SINGLE);
  let done = 0;
  await Promise.all(jobs.map(key => new Promise((resolve) => {
    loader.load(TEX + key + '.webp', t => {
      t.wrapS = t.wrapT = THREE.RepeatWrapping;
      t.anisotropy = anisotropy;
      if (key.endsWith('_albedo') && key !== 'puddles_albedo' && key !== 'marking_albedo' && key !== 'yardmask_albedo') t.colorSpace = THREE.SRGBColorSpace;
      textures[key] = t;
      done++; onProgress?.(done / jobs.length);
      resolve();
    }, undefined, () => { console.warn('texture failed', key); done++; resolve(); });
  })));
  WET.tPuddle.value = textures.puddles_albedo;
  WET.tYard.value = textures.yardmask_albedo || textures.puddles_albedo;
}

function repeatClone(tex, rep) {
  if (!tex) return null;
  if (rep === 1) return tex;
  const t = tex.clone();
  t.repeat.set(rep, rep);
  t.needsUpdate = true;
  return t;
}

const cache = new Map();
/**
 * mat('asphalt', {wet:'ground'}) – textured PBR material with rain extension.
 * opts: tile (override), color, wet: 'ground'|'surface'|'none', normalScale, envMapIntensity, roughness, metalness
 */
export function mat(set, opts = {}) {
  const key = set + JSON.stringify(opts);
  if (cache.has(key)) return cache.get(key);
  const info = SETS[set];
  const rep = 1 / (opts.tile ?? info.tile);
  const params = {
    map: repeatClone(textures[set + '_albedo'], rep),
    normalMap: repeatClone(textures[set + '_normal'], rep),
    roughnessMap: repeatClone(textures[set + '_orm'], rep),
    aoMap: repeatClone(textures[set + '_orm'], rep),
    aoMapIntensity: 0.9,
    roughness: opts.roughness ?? 1,
    metalness: info.kind === 'metal' ? (opts.metalness ?? 1) : 0,
    normalScale: new THREE.Vector2(opts.normalScale ?? 1, opts.normalScale ?? 1),
    envMapIntensity: opts.envMapIntensity ?? 1,
  };
  if (info.kind === 'metal') params.metalnessMap = params.roughnessMap;
  if (opts.color) params.color = new THREE.Color(opts.color);
  if (opts.side) params.side = opts.side;
  const m = new THREE.MeshStandardMaterial(params);
  addWet(m, opts.wet ?? 'surface', info.kind === 'ground', info.macro);
  cache.set(key, m);
  return m;
}

export function plainMat(color, roughness = 0.6, metalness = 0, extra = {}) {
  const { wet = 'surface', ...rest } = extra;
  const m = new THREE.MeshStandardMaterial({ color, roughness, metalness, ...rest });
  addWet(m, wet, false);
  return m;
}

const WET_COMMON = /* glsl */`
uniform float uTime;
uniform float uWetness;
uniform sampler2D tPuddle;
varying vec3 vWetPos;
varying vec3 vWetN;
float wetHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
`;

const WET_GROUND_DECL = /* glsl */`
uniform sampler2D tYard;
uniform sampler2D tRefl;
uniform mat4 uReflMatrix;
uniform float uReflOn;
// Expanding rain-drop rings on standing water, returns world-space xz slope.
vec2 rainRipple(vec2 p, float t){
  vec2 slope = vec2(0.0);
  for (int k = 0; k < 2; k++) {
    vec2 q = p * (k == 0 ? 2.6 : 3.7) + float(k) * 17.3;
    vec2 cell = floor(q); vec2 f = fract(q);
    for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
      vec2 c = cell + vec2(float(i), float(j));
      float h = wetHash(c);
      vec2 center = vec2(float(i), float(j)) + vec2(wetHash(c + 3.1), wetHash(c + 7.7));
      float phase = fract(t * (0.8 + 0.4 * h) + h);
      vec2 d = f - center; float r = length(d);
      float x = (r - phase * 0.75) * 16.0;
      float a = (1.0 - phase); a *= a;
      slope += d / (r + 1e-3) * sin(x * 3.14159) * exp(-x * x * 0.5) * a;
    }
  }
  return slope * 0.25;
}
`;

// Specular anti-aliasing (Toksvig): mip-filtered normal maps get shorter where the
// detail they averaged was bumpy; widen the GGX lobe accordingly so fine aggregate,
// weave and scratches do not sparkle at a distance. Puddles (tbKeep) are exempt.
const TOKSVIG = /* glsl */`
  {
    float tbLen = max(length(mapN), 1e-3);
    float tbVar = max((1.0 - tbLen) / tbLen - 0.004, 0.0) * dot(normalScale, normalScale) * 0.5;
    float tbA = roughnessFactor * roughnessFactor;
    float tbR = sqrt(sqrt(min(tbA * tbA + 2.0 * tbVar, 1.0)));
    roughnessFactor = mix(tbR, roughnessFactor, tbKeep);
  }
  mapN.xy *= normalScale;`;

// Container paint: per-instance, per-1.5 m-band horizontal shift (and mirror) of the
// 3 m paint tile. Bands follow the vertical corrugation so the cut is not noticed;
// textureGrad keeps the mip level continuous across band edges.
const CONTAINER_UV = /* glsl */`
varying float vTbSeed;
vec2 tbUv(vec2 uv) {
  float bw = 0.5;                                  // band width in u (= 1.5 m)
  float band = floor(uv.x / bw + vTbSeed * 13.0);
  float h = wetHash(vec2(band, vTbSeed * 71.3));
  float fl = step(0.5, wetHash(vec2(band + 3.7, vTbSeed * 17.9)));
  float c = (band - vTbSeed * 13.0 + 0.5) * bw;   // band centre in u
  float u = mix(uv.x, 2.0 * c - uv.x, fl) + floor(h * 6.0) / 6.0;
  return vec2(u, uv.y);
}
`;
const TB_SAMPLE = /texture2D\(\s*(map|normalMap|roughnessMap|metalnessMap|aoMap),\s*(vMapUv|vNormalMapUv|vRoughnessMapUv|vMetalnessMapUv|vAoMapUv)\s*\)/g;
const tbVar = (chunk) => chunk.replace(TB_SAMPLE, 'textureGrad($1, tbUv($2), dFdx($2), dFdy($2))');

function addWet(material, mode, ground, macro) {
  const wetOn = mode !== 'none';
  const isGround = mode === 'ground';
  const yard = isGround && macro === 'yard';
  const cont = macro === 'container';
  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, WET);
    const defs = { ...(shader.defines || {}) };
    if (isGround) defs.WET_GROUND = '';
    if (ground) defs.ORM_HEIGHT = '';
    if (yard) defs.YARD_MACRO = '';
    shader.defines = defs;
    let vs = shader.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vWetPos;\nvarying vec3 vWetN;' + (cont ? '\nvarying float vTbSeed;' : ''));
    vs = vs.replace('#include <fog_vertex>', `#include <fog_vertex>
      {
        vec4 wp = vec4(transformed, 1.0);
        vec3 on = objectNormal;
        vec3 seedP = modelMatrix[3].xyz;
        #ifdef USE_INSTANCING
          wp = instanceMatrix * wp; on = mat3(instanceMatrix) * on;
          seedP += instanceMatrix[3].xyz;
        #endif
        wp = modelMatrix * wp; vWetPos = wp.xyz;
        vWetN = normalize(mat3(modelMatrix) * on);
        ${cont ? 'vTbSeed = fract(sin(dot(seedP, vec3(12.9898, 78.233, 37.719))) * 43758.5453);' : ''}
      }`);
    shader.vertexShader = vs;

    const C = THREE.ShaderChunk;
    let mapChunk = cont ? tbVar(C.map_fragment) : '#include <map_fragment>';
    if (isGround) mapChunk = `
      // stochastic two-sample blend breaks up visible texture tiling on large ground areas
      float wBlend = smoothstep(0.38, 0.62, texture2D(tPuddle, vWetPos.xz / 17.0 + 0.5).r);
      vec2 wUv2 = mat2(0.8, -0.6, 0.6, 0.8) * vMapUv * 0.71 + 0.31;
      #ifdef USE_MAP
        diffuseColor *= mix(texture2D(map, vMapUv), texture2D(map, wUv2), wBlend);
      #endif
      // world-scale tone so neighbouring 4 m tiles never match exactly
      diffuseColor.rgb *= 0.9 + 0.2 * texture2D(tPuddle, vWetPos.xz / 31.0 + 0.13).r;
      #ifdef YARD_MACRO
        // repairs, sealed cracks, big stains, wheel paths, ghosted markings (64 m mask)
        vec3 ym = texture2D(tYard, vWetPos.xz / 64.0 + 0.5).rgb;
        float yPw = max(fwidth(ym.r), 1e-3);
        float yPatch = smoothstep(0.5 - yPw, 0.5 + yPw, ym.r);
        float ySw = max(fwidth(ym.b), 1e-3);
        float ySeal = smoothstep(0.5 - ySw, 0.5 + ySw, ym.b);
        float yTone = (ym.g - 0.5) * 2.0;
        float yEdge = (1.0 - smoothstep(0.0, 0.025 + 2.0 * yPw, abs(ym.r - 0.5))) * step(0.004, ym.r);
        diffuseColor.rgb *= clamp(1.0 + yTone * 0.9, 0.35, 1.6) * (1.0 - 0.45 * yEdge);
        diffuseColor.rgb = mix(diffuseColor.rgb, vec3(0.017, 0.017, 0.018), ySeal * 0.92);
      #endif
      `;
    let fs = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nfloat tbKeep = 0.0;\n' + WET_COMMON + (isGround ? WET_GROUND_DECL : '') + (cont ? CONTAINER_UV : ''))
      .replace('#include <map_fragment>', mapChunk);
    if (cont) {
      fs = fs.replace('#include <roughnessmap_fragment>', tbVar(C.roughnessmap_fragment))
        .replace('#include <aomap_fragment>', tbVar(C.aomap_fragment));
    }
    const metalChunk = cont ? tbVar(C.metalnessmap_fragment) : '#include <metalnessmap_fragment>';
    let normalChunk = C.normal_fragment_maps;
    if (isGround) normalChunk = normalChunk.replace('vec3 mapN = texture2D( normalMap, vNormalMapUv ).xyz * 2.0 - 1.0;',
      'vec3 mapN = mix(texture2D( normalMap, vNormalMapUv ).xyz, texture2D( normalMap, mat2(0.8, -0.6, 0.6, 0.8) * vNormalMapUv * 0.71 + 0.31 ).xyz, wBlend) * 2.0 - 1.0;');
    if (cont) normalChunk = tbVar(normalChunk);
    normalChunk = normalChunk.replace('mapN.xy *= normalScale;', TOKSVIG);
    fs = fs.replace('#include <normal_fragment_maps>', normalChunk);
    if (!wetOn) {
      fs = fs.replace('#include <metalnessmap_fragment>', metalChunk);
      shader.fragmentShader = fs;
      return;
    }
    fs = fs.replace('#include <metalnessmap_fragment>', metalChunk + `
      vec3 wN = normalize(vWetN);
      float wUp = smoothstep(0.55, 0.95, wN.y);
      float wet = uWetness;
      float puddle = 0.0;
      float wMetal = metalnessFactor;
      // porous rough dielectrics (asphalt, concrete, wood, fabric) darken a lot when soaked,
      // sealed paint barely; metals keep their specular colour (Lagarde 2013)
      float porosity = smoothstep(0.35, 0.9, roughnessFactor) * (1.0 - wMetal);
      float soak = wet * mix(0.55, 1.0, wUp);
      #ifdef YARD_MACRO
        roughnessFactor *= clamp(1.0 + yTone * 0.6, 0.5, 1.3);
        roughnessFactor = mix(roughnessFactor, 0.3, ySeal);
      #endif
      #ifdef WET_GROUND
        float hgt = 0.5;
        #if defined(ORM_HEIGHT) && defined(USE_ROUGHNESSMAP)
          hgt = texture2D(roughnessMap, vRoughnessMapUv).b;
        #endif
        float pm = texture2D(tPuddle, vWetPos.xz / 46.0).r;
        float pm2 = texture2D(tPuddle, vWetPos.xz / 9.0 + 0.37).r;
        float level = pm * 0.8 + pm2 * 0.2 + (0.5 - hgt) * 0.18;
        #ifdef YARD_MACRO
          level += yPatch * 0.035 - ySeal * 0.03;     // settled repairs hold water, sealant ridges shed it
        #endif
        puddle = smoothstep(0.56, 0.6, level) * wUp * wet;
        float damp = smoothstep(0.42, 0.56, level) * wUp * wet; // saturated dark film around puddles
        diffuseColor.rgb *= mix(1.0, 0.82, damp);
        roughnessFactor = mix(roughnessFactor, roughnessFactor * 0.6, damp);
      #else
        // vertical surfaces: rain run-off streaks
        float streak = texture2D(tPuddle, vec2(vWetPos.x * 0.37 + vWetPos.z * 0.37, vWetPos.y * 0.03)).r;
        roughnessFactor = mix(roughnessFactor, roughnessFactor * mix(0.55, 0.9, streak), wet * (1.0 - wUp));
      #endif
      diffuseColor.rgb *= mix(1.0, mix(0.9, 0.6, porosity), soak);
      roughnessFactor = mix(roughnessFactor, roughnessFactor * mix(0.6, 0.85, wMetal), wet * wUp);
      #ifdef WET_GROUND
        // floor so distant ground keeps a broad wet sheen instead of noise (Toksvig adds more)
        float nVar = length(fwidth(vWetPos.xz)) * 2.0;
        roughnessFactor = max(roughnessFactor, clamp(0.24 + nVar, 0.24, 0.6));
      #endif
      diffuseColor.rgb *= mix(1.0, 0.7, puddle);
      roughnessFactor = mix(roughnessFactor, 0.02, puddle);
      metalnessFactor = mix(metalnessFactor, 0.0, puddle);
      tbKeep = puddle;
      `)
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
      #ifdef WET_GROUND
      if (puddle > 0.001) {
        vec2 rip = rainRipple(vWetPos.xz, uTime);
        vec3 rippleV = normalize((viewMatrix * vec4(normalize(vec3(-rip.x, 1.0, -rip.y)), 0.0)).xyz);
        normal = normalize(mix(normal, rippleV, puddle));
      }
      #endif
      `)
      .replace('#include <opaque_fragment>', `
      #ifdef WET_GROUND
      // Standing water is near-perfectly smooth: a punctual-light GGX lobe would read as a soft,
      // blown-out blob. Let the mirrored scene provide the lamp image instead, and keep only a
      // clamped glint (low preset has no mirror pass, so it keeps more of the glint).
      {
        vec3 ds = reflectedLight.directSpecular;
        float keep = uReflOn > 0.5 ? 0.12 : 0.35;
        outgoingLight -= ds * puddle;
        outgoingLight = max(outgoingLight, vec3(0.0)) + min(ds, vec3(1.5)) * puddle * keep;
      }
      if (uReflOn > 0.5) {
        vec4 rc = uReflMatrix * vec4(vWetPos, 1.0);
        vec2 ruv = rc.xy / rc.w;
        vec3 nW = (vec4(normal, 0.0) * viewMatrix).xyz;
        ruv += nW.xz * 0.05;
        float lod = clamp(roughnessFactor * 9.0, 0.0, 6.0);
        float sp = 0.004 + roughnessFactor * 0.05; // vertical streaking like wet tarmac
        vec3 refl = textureLod(tRefl, ruv, lod).rgb * 0.4
                  + textureLod(tRefl, ruv + vec2(0.0, sp), lod).rgb * 0.2
                  + textureLod(tRefl, ruv - vec2(0.0, sp), lod).rgb * 0.2
                  + textureLod(tRefl, ruv + vec2(0.0, sp * 2.2), lod + 1.0).rgb * 0.1
                  + textureLod(tRefl, ruv - vec2(0.0, sp * 2.2), lod + 1.0).rgb * 0.1;
        refl = min(refl, vec3(6.0)); // keep lamp reflections as crisp streaks instead of blooming blobs
        float NdV = clamp(dot(normal, normalize(vViewPosition)), 0.0, 1.0);
        float F = 0.02 + 0.98 * pow(1.0 - NdV, 5.0);
        float rw = F * wet * mix(0.35, 1.0, puddle) * (1.0 - clamp(roughnessFactor, 0.0, 1.0) * 0.85);
        outgoingLight += refl * rw;
      }
      #endif
      #include <opaque_fragment>`);
    shader.fragmentShader = fs;
  };
  material.customProgramCacheKey = () => 'wet-' + mode + (ground ? '-h' : '') + (macro ? '-' + macro : '') + '-v3';
}

export function updateWet(time) { WET.uTime.value = time; }
